// Stepper motion module (M0-T003; implements IMotion since M0-T010).
//
// Owns the FastAccelStepper instance. Steps are generated by the ESP32 RMT
// peripheral (hardware-timed), so WiFi/scheduler preemption no longer jitters
// the pulse train; FastAccelStepper runs its own stepper task, replacing the
// AccelStepper polling task + portMUX of M0-T003. Two physical motors are
// driven synchronously from the same STEP/DIR signals; each driver has its own
// active-low EN line (EN1 GPIO5, EN2 GPIO23), always switched together.
//
// Gear/feed conversion (steps per mm, rpm to steps/s) stays in
// lib/FirmwareCore; command handlers compute step targets with it and hand
// them to startMoveToSteps().
#pragma once

#include <Arduino.h>
#include <FastAccelStepper.h>

#include "IMotion.h"

class Motion : public IMotion {
 public:
  // Pins, FastAccelStepper config, initial speed.
  void begin() override;

  void enable() override;
  void disable() override;  // stops motion, turns outputs off

  void stop() override;  // stops motion, driver stays enabled

  void zero() override;  // sets the axis position to 0 steps

  void setOutputRpm(float rpm) override;
  void setAccelRpmPerS(float accelRpmPerS) override;
  float outputRpm() override;
  float accelRpmPerS() override;

  // Moves to an absolute step target; enables the driver first (legacy
  // startMoveTo behavior).
  void startMoveToSteps(long targetSteps) override;

  // #158: sign of (target - current) while a moveTo is in flight - the
  // plain-move endstop guard needs the travel direction. 0 when idle.
  int8_t moveDirection() override;

  // Continuous run at the current speed (runForward/runBackward, M3
  // FR-001 homing seeks); enables the driver first like startMoveToSteps.
  void startContinuous(int direction) override;

  // Immediate stop without ramp (M3 plan D5); flushes the command queue
  // so a queued moveTo cannot restart the motor afterwards.
  void forceStop() override;

  bool isEnabled() override;
  bool isRunning() override;
  long steps() override;
  float positionMm() override;

 private:
  void applySettings();

  // Runtime config (legacy main.cpp values). begin() derives the initial
  // rpm from kDefaultFeedMmPerMin (the 30 mm/min travel default,
  // bench-established 2026-10-11), so outputRpm_ starts at 15.0 and
  // becomes feedMmPerMinToRpm(30) = 15.0 in begin() (travel moves).
  static constexpr float kDefaultOutputRpm = 5.0f;
  static constexpr float kDefaultAccelRpmPerS = 20.0f;
  static constexpr float kDefaultFeedMmPerMin = 30.0f;

  static constexpr uint8_t kDirPin = 19;
  static constexpr uint8_t kStepPin = 18;
  static constexpr uint8_t kEnPin = 5;    // EN1, motor 1 (active low)
  static constexpr uint8_t kEn2Pin = 23;  // EN2, motor 2 (active low)

  FastAccelStepperEngine engine_;
  FastAccelStepper *stepper_ = nullptr;
  float outputRpm_ = kDefaultOutputRpm;
  float accelRpmPerS_ = kDefaultAccelRpmPerS;
  bool driverEnabled_ = false;
};
